INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2680','מקומה של האסתטיקה בחינוך ולדורף','עבודה סמינריונית','מגישה: אורי גלעדי מנחה: דר'' גלעד גולדשמידט מתוך המבוא לעבודה: ''עלינו להדגיש שוב ושוב, שתפיסת העולם האנתרופוסופית מטפחת תודעה – שבין תחומי האמנות, הדת והמדע – שוררים יחסי…','./lib-p2680.html','אורי גלעדי','2020',0,24,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2586','הומור בחינוך האנתרופוסופי','עבודה סמינריונית','סמינריון בחינוך, מכללת דוד ילין מנחה: ד"ר גלעד גולדשמידט מגישה: שרה מלכה מרץ 2020 הקדמה בחרתי לעסוק בעבודה זו בנושא ההומור, מכיוון שמשחר ילדותי אני זוכרת כיצד ההומור…','./lib-p2586.html','שרה מלכה','2020',0,25,strftime('%s','now'),strftime('%s','now'));
