INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2545','הומור וחינוך ולדורף','עבודה','מתוך ההקדמה: הבחירה לעסוק בעבודה זו בנושא ההומור, ובעיקר הומור בקרב אנשי חינוך בחינוך ולדורף , הגיעה אליי מתוך ההבנה כי לאורך לימודיי בחינוך ולדורף נדמה היה כי מעולם לא…','./lib-p2545.html','ליאת אדלר','2019',0,29,strftime('%s','now'),strftime('%s','now'));
