INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2522','שנים עשר החושים לאור האנתרופוסופיה ומשמעותם לחינוך','עבודה','העבודה עוסקת בתפיסת שנים עשר החושים על פי מדע הרוח האנתרופוסופיה. חינוך ולדורף על פי – משנתו של ד"ר רודולף שטיינר שחקר את התפתחות האדם והאנושות בראי מדע הרוח והטבע, עוסק…','./lib-p2522.html','רעות אתרוגי','2019',0,34,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2519','האם תכנית הלימודים במדעים בכיתות ו'' ז'' ח'' בבתי ספר ולדורף הולמת את התפתחות הילד? ואם כן כיצד?','עבודה סמינריונית','העבודה נכתבת במסגרת הכשרת מורי ולדורף במכללת דוד ילין. מכיוון שאני עוסק בהוראת המדעים ומחנך כיתה בבי"ס יחיאל, בי"ס ולדורף בטל שחר, בחרתי לעסוק בהוראת המדעים. לפעמים נדמה…','./lib-p2519.html','תום נוימן','2019',0,35,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2479','האם  וכיצד עקרונות יסוד מתוך הפסיכולוגיה החיובית באים לידי ביטוי בחינוך וולדורף בשביעון השני','עבודה סמינריונית','מכללת דוד ילין עבודת סמינריון [ להורדת העבודה כקובץ PDF ] מנחים: ד"ר גלעד גולדשמידט ד"ר בועז צבר מגיש: יובל קפל 07/3/2019 "שאיפתנו העליונה היא לפתח בני אדם חופשיים,…','./lib-p2479.html','יובל קפל','2019',0,36,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2411','דרכים ליישום החינוך העמלני באמצעות עבודת אדמה','עבודה סמינריונית','עבודת סמינריון דרכים ליישום החינוך העמלני באמצעות עבודת אדמה. התנסותי כמורה במסגרת הקמת חווה חקלאית בבית הספר האנתרופוסופי "עליה" בבת גלים. מוגש על ידי: עמיר פרי…','./lib-p2411.html','עמיר פרי','2018',0,37,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2410','מה בין חינוך ולדורף לבין החינוך ''מבוסס-טבע'' בעבודת גן הילדים','עבודה סמינריונית','המכללה האקדמית לחינוך ע"ש דוד ילין סמינריון בחינוך (ולדורף מורים בפועל מחזור ב'') תשע"ח עבודה סמינריונית בנושא: מה בין חינוך ולדורף לבין החינוך ''מבוסס-טבע'' בעבודת גן…','./lib-p2410.html','אביב קידר','2018',0,38,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2389','התאמות בחינוך ולדורף – השוואה בין מאפייני חינוך ולדורף חילוני לבין דתי יהודי','עבודה סמינריונית','סמינריון: התאמות בחינוך ולדורף – השוואה בין מאפייני חינוך ולדורף חילוני לבין דתי יהודי מאת: ענת עציץ בעבודה זו ברצוני לבדוק כיצד התאוריה החינוכית של ולדורף באה לידי…','./lib-p2389.html','ענת עציץ','2018',0,39,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2372','הוראת המוזיקה בשנים הראשונות בבית ספר ולדורף','עבודה סמינריונית','מאת: מוטי עמיר במסגרת קורס: סמינריון בחינוך (ולדורף מורים בפועל מחזור ב'') המרצים: ד"ר בועז צבר, ד"ר גלעד גולדשמיט ״כל אדם מסוגל ליצור, וכן מסוגל כל ילד ליצור, באשר כושר…','./lib-p2372.html','מוטי עמיר','2018',0,40,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2357','כיצד לימודי האומנות הפלסטית בתיכון ולדורף תומכים בהתפתחות הנוער? | עפרה קנה','עבודה סמינריונית','עבודה סמינריונית מנחה: דר'' גלעד גולדשמידט מגישה: עפרה קנה עפרה קנה אומנות בבית ספר ולדורף תיכון [העבודה כקובץ word] מבוא במציאות של ימינו הנחות היסוד המתבססות על ידע…','./lib-p2357.html',NULL,'2018',0,41,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2353','סמכות המחנך בחינוך ולדורף','עבודה סמינריונית','עבודה סמינריונית בחינוך מאת אשר וזה מנחה: ד"ר גלעד גולדשמידט סמינריון בחינוך סמכות המורה [העבודה כקובץ word] תוכן העניינים מבוא כללי פרק ראשון: סקירה כללית של סמכות…','./lib-p2353.html','אשר וזה','2018',0,42,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2347','פיסול בחינוך וולדורף – הלכה למעשה על הקשר שבין פיסול לחיזוק כוחות הרצון','עבודה סמינריונית','עבודת סמינריון מאת רעות לביא מנחים: בועז צבר, גלעד גולדשמידט בעבודה זו אציג את כלי העבודה הנפלא של פיסול חינוכי בחינוך וולדורף, וכיצד תורם ותומך את התפתחות הילד בשלבי…','./lib-p2347.html','רעות לביא','2018',0,43,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2349','חינוך ולדורף וחינוך יהודי – "הילכו שניהם יחדיו?"','עבודה סמינריונית','מאת ינון קמון מנחה: ד"ר איתן שיקלי תאריך: אפריל 2018, ניסן תשע"ח חינוך ולדורף וחינוך יהודי – "הילכו שניהם יחדיו?" מהן הזיקות וקווי המתאר המשותפים לחינוך ולדורף בישראל…','./lib-p2349.html','ינון קמון','2018',0,44,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2339','מימוש פילוסופית החינוך האנתרופוסופי במבני חינוך ולדורף','עבודה סמינריונית','סמינריון תמטי בחינוך וארכיטקטורה מגישים: יהלי קפל ואיתמר נייגר // שנה אקדמית ד'' // התשע"ד מנחים: ד"ר איתן מכטר וד"ר ליאורה ברעם-שחל ארכיטקטורה וחינוך ולדורף','./lib-p2339.html','יהלי קפל ואיתמר נייגר','2018',0,45,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2341','כיצד תומכים המבנים שבהם שוכנים בתי ספר וגני וולדורף בפעילות החינוכית המתרחשת בתוכם?','עבודה סמינריונית','עבודה סמינריונית בחינוך מאת עדי בלוכביץ מנחים: ד"ר גלעד גולדשמידט, ד"ר בועז צבר עבודה סמינריונית על אריכטקטורה של בתי ספר ולדורף (כולל איורים כקובץ word) מבוא כאשר…','./lib-p2341.html','עדי בלוכביץ','2018',0,46,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2338','האם וכיצד נותן חינוך וולדרוף מענה לילדים אשר חוו טראומה בילדותם?','עבודה סמינריונית','עבודת סמינריון מאת עידן יהב מנחים: גלעד גולדשמידט ובועז צבר מבוא נושא המחקר של עבודתי הוא : האם וכיצד נותן חינוך וולדרוף מענה לילדים אשר חוו טראומה בילדותם? אל השאלה…','./lib-p2338.html','עידן יהב','2018',0,47,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2320','על סינתזה ואנליזה בהוראת המתמטיקה בחטיבת הביניים','עבודה','מאת: ניצן פריימן הקדמה חיבור זה נכתב בעיקר עבור מורי מתמטיקה בכיתות ז'' ח'', אך אני מאמין כי ניתן לפתח את הכיוונים שאביא בו גם עבור הוראת המתמטיקה בכיתות הצעירות יותר.…','./lib-p2320.html','ניצן פריימן','2018',0,48,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2319','התפתחות לימודי השירה והמוזיקה בבית ספר ולדורף ומשמעותם לחינוך ולהוראה | מור גולדשמידט','עבודה סמינריונית','עבודה סמינריונית | מור גולדשמידט | אוגוסט 2011 מבוא עבודה זו מוגשת כעבודה סמינריונית במסגרת קורס של האופרה במאה ה-20 וה-21. היא עוסקת בתוכנית הלימודית בתחום המוסיקה בבית…','./lib-p2319.html',NULL,'2018',0,49,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3245','רגע היציאה מהכיתה: על אמנות הפרידה בסוף יום לימודים','מאמר','כיצד רגע הפרידה בסוף יום הלימודים משפיע על התלמידים? על חשיבות המעברים, סגירה פדגוגית ואמנות הפרידה בחינוך ולדורף.','./lib-p3245.html',NULL,'2026',0,1000,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3242','אומנות הושבת התלמידים בכיתה','מאמר','סידור מקומות הישיבה בכיתת ולדורף הוא אינו רק עניין לוגיסטי – הוא כלי חינוכי ראשון במעלה. הרצון ליצור ריתמוס נכון ואווירה לימודית תומכת דורש מאיתנו התחשבות רבה: החל…','./lib-p3242.html',NULL,'2026',0,1001,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3240','מבט על פלא החברות ארוכת השנים','מאמר','איך זה קורה שבוגרים ובוגרות שסייימו ללמוד לפני שנים, עדיין בוחרים להעביר את ימי החופש היקרים שלהם יחד מעבר לים? מהו ה"דבק" שנזרע בנפשם ומחזיק מעמד לאורך שנים? מאמר על…','./lib-p3240.html',NULL,'2026',0,1002,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3236','איך נולדת תקופה?','מאמר','מה באמת קורה מאחורי הקלעים של בניית תקופה בחינוך ולדורף? עבור הילדים, התקופה מתחילה כשהמורה נכנס לכיתה ומתחיל ללמד. אבל עבור המחנך היא מתחילה שבועות ואף חודשים קודם לכן.…','./lib-p3236.html',NULL,'2026',0,1003,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3218','זה היה בחברות – מדריך למחנך להתמודדות עם אלימות ומשחקי נערים בגיל המצווה','מאמר','כשבני כיתה ו'' נכנסים מההפסקה חבולים וסוערים, אנחנו המחנכים ניצבים בפני צומת מורכב. האם זו אלימות שיש להעניש עליה, או שפה פנימית של כוחות רצון המחפשים ערוץ לביטוי? במאמר…','./lib-p3218.html',NULL,'2026',0,1004,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3215','ימי מונדיאל: מה בין כדורגל ובין חינוך ולדורף?','מאמר','כדורגל הוא ללא ספק המשחק הפופולרי ביותר בעולם. עבור ילדים רבים, הוא אינו רק פעילות גופנית אלא מרכז הזהות החברתית שלהם, שפה בינלאומית ומושא להערצה. עם זאת, בתוך מסורת…','./lib-p3215.html',NULL,'2026',0,1005,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3201','אחריות אישית: ממושג פילוסופי לפרקטיקה חינוכית ואזרחית','מאמר','מאמר הבוחן את ערך האחריות האישית כגשר בין חירות הפרט למחויבות חברתית. גלו את המתח שבין האתיקה המוסרית לגישה התועלתנית, את הבשורה של האנתרופוסופיה וחינוך ולדורף בטיפוח…','./lib-p3201.html',NULL,'2026',0,1006,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3197','"קבל את הילד ביראה, חנך אותו באהבה ושלחהו לדרכו בחירות"','מאמר','חזון החינוך על פי רודולף שטיינר: בין יראה, אהבה וחירות בשנת 1919, במסגרת הכשרת המורים הראשונה של בית ספר ולדורף, טבע רודולף שטיינר את המשפט שהפך לאבן היסוד של הגישה…','./lib-p3197.html',NULL,'2026',0,1007,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3186','מעבר לעיקול הדרך: מדוע הריקנות של המחנך היא הצלחתו הגדולה ביותר?','מאמר','מאת: ירון זנבל , מרץ 2026 אחרי שנים של מסע משותף, מגיע רגע הפרידה הטעון. מדוע הריקנות שחש המחנך היא בעצם עדות להצלחה חינוכית? ואיך הופכת ה"שמש" הכיתתית ל"ירח" המלווה…','./lib-p3186.html','ירון זנבל','2026',0,1008,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3181','אידיאל המחנך ל-8 שנים בחינוך ולדורף פוגש את המציאות','מאמר','מאת: לינה בטשון מעווד וירון זנבל בבסיס חינוך ולדורף עומד האידיאל של מחנך המלווה את כיתתו לאורך כל שנות בית הספר היסודי (מכיתה א'' ועד ח''). מודל זה מבקש לייצר עבור הילד…','./lib-p3181.html',NULL,'2026',0,1009,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3178','תקופות הלימוד (הבלוקים) בכיתות א''-ט''','מאמר','מאת ירון זנבל, מרץ 2026 תקופות הלימוד (הבלוקים) הן מאבני היסוד של פדגוגיית ולדורף. בשיטה זו, במקום מערכת שעות מקוטעת, התלמידים צוללים לנושא אחד לעומק במשך מספר שבועות…','./lib-p3178.html','ירון זנבל','2026',0,1010,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3169','למידה מרחוק בעת חירום בחינוך ולדורף','מאמר','גם בלמידה מרחוק, חינוך ולדורף נשאר נאמן לעקרונותיו. הלמידה המקוונת בחירום אינה הופכת לדיגיטלית יותר, אלא ל"אנושית יותר" – היא משתמשת בטכנולוגיה כגשר זמני כדי לאפשר לילד…','./lib-p3169.html','ירון זנבל','2026',0,1011,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3164','מקונפליקט לחיבור: ריפוי חברתי באמצעות פרקטיקות בהשראת חינוך וולדורף','מאמר','המאמר, שנכתב בידי אייל בלוך ותום שייפר, מציג מסע מבוסס עקרונות לשיקום חברתי באזורי סכסוך. המאמר מתבסס על שלושה עשורים של עבודה בשטח ומשלב בין הפילוסופיה החינוכית של…','./lib-p3164.html',NULL,'2026',0,1012,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3147','פרדוקס הדיגיטציה בחינוך: בין קדמה טכנולוגית לבין נסיגה קוגניטיבית','מאמר','מאת: ירון זנבל בעוד מערכת החינוך דוהרת לעבר דיגיטציה מלאה תחת ההבטחה להכין את התלמידים למאה ה-21, המציאות בשטח חושפת תמונה הפוכה ומדאיגה. המסכים, שאמורים היו להנגיש ידע,…','./lib-p3147.html',NULL,'2026',0,1013,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3145','מה הטמפרמנט שלי?','מאמר','הרבה לפני שהכרנו את כל החומרים שבטבלה המחזורית, היוונים העתיקים האמינו שהעולם מורכב מ-4 יסודות בסיסיים שיוצרים את כל החומרים שבעולם – אש 🔥, מים 💧, רוח 🌬️ ואדמה ⛰️.…','./lib-p3145.html',NULL,'2026',0,1014,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3139','המהפכה של גיל הנעורים והמענה של חינוך ולדורף','מאמר','מאת ירון זנבל, ינואר 2026 חינוך ולדורף בגילאי חט"ב מבקש לבנות עבור המתבגר "כלי שיט" שייסיע לו במסע המטלטל בין "יבשת" הילדות הבטוחה, לבין "אי" ההתבגרות. דרך שילוב בין…','./lib-p3139.html','ירון זנבל','2026',0,1015,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3137','שברים פשוטים?! אתגרים בהוראת השברים והמענה של חינוך ולדורף','מאמר','מאת ירון זנבל, ינואר 2026 לימוד שברים נחשב לאחת המשימות המאתגרות ביותר במתמטיקה של בית הספר היסודי, עד כדי כך שבעבר הרחוק הם נלמדו רק ברמה האוניברסיטאית – המעבר למספרים…','./lib-p3137.html','ירון זנבל','2026',0,1016,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3134','בין המוביל לבין המאסף: טמפרמנט המחנך כמפת דרכים חינוכית','מאמר','מאת ירון זנבל, ינואר 2026 המאמר מציג את עבודת המחנך דרך המטאפורה של הטיול השנתי, הנעה בין המורה המוביל המקרין ביטחון בראש השיירה למורה המאסף המלווה ברגישות מאחור. דרך…','./lib-p3134.html','ירון זנבל','2026',0,1017,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3130','הערכה מילולית בטווחים: מודדים את בריאות הלמידה','מאמר','מאת: ירון זנבל, דצמבר 2025 אבחון במקום ציון הערכה מבוססת ציון מספרי יוצרת אוטומטית השוואה ודירוג. הבעיה אינה רק הציון עצמו, אלא המסר המוסרי והחברתי שהוא משדר. חינוך…','./lib-p3130.html','ירון זנבל','2025',0,1018,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3112','המסע המחנך: טיולים בחינוך ולדורף','מאמר','לצאת מהכיתה, לפגוש את העולם, להקשיב לדממה ולנשום את הטבע. הטיול בחינוך ולדורף אינו רק מטרה, אלא אמצעי לעיצוב אדם מחובר, המסוגל לאהוב את העולם הרחב. חווית הטיול, המסומנת…','./lib-p3112.html',NULL,'2025',0,1019,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3110','התבוננות בילד: פרקטיקה של הכרה וריפוי','מאמר','מאת: ירון זנבל, נובמבר 2025 מהי ההתבוננות? ההתבוננות בילד היא פרקטיקה פנומנולוגית-רפלקטיבית ושיטה טיפולית המעוגנת בתורתו הביוגרפית-התפתחותית של רודולף שטיינר. בחדר…','./lib-p3110.html','ירון זנבל','2025',0,1020,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3106','בינה מלאכותית בשירות חינוך ולדורף: נתיב לשימוש מושכל','מאמר','האם בינה מלאכותית (AI) מאיימת על עקרונות חינוך ולדורף, או שמא היא כלי הכרחי שיש לרתום? המאמר מתווה נתיב סינרגטי המבחין בין שימוש המורים ב-AI לבין הוראת התלמידים ומציע כי…','./lib-p3106.html',NULL,'2025',0,1021,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3104','השילוב בין אינטואיציות המחנך ובין יכולות AI בליהוק הצגות כיתה','מאמר','הצגת הכיתה בחינוך ולדורף מוגדרת כשיא הפעילות החינוכית של בית הספר והיא מהווה כור היתוך יצירתי, רגשי וחברתי. בהיותה תהליך מורכב, היא מטילה עומס על המחנכים וצוות ביה"ס.…','./lib-p3104.html','ירון זנבל','2025',0,1022,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3099','איך לקבל החלטת גורל','מאמר','כאשר אנו מזהים קושי או צורך בשינוי, והפתרון כרוך בבחירה בין חלופות – אנו עומדים בפני ה צורך לקבל החלטה . אנו נדרשים לקבל החלטות פעמים רבות במהלך חיינו – לצד החלטות…','./lib-p3099.html','ירון זנבל','2025',0,1023,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3086','מדריך לכריכת מחברות תקופה לספר השנה','מאמר','מחברת התקופה בחינוך ולדורף היא אמצעי מרכזי לתיעוד תהליך הלמידה שמתרחש במהלך תקופות הלימוד. כל מחברת כוללת סיכומים בכתב, ציורים, סיפורים, שירים וכתיבה אישית של התלמיד.…','./lib-p3086.html','ירון זנבל','2025',0,1024,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3088','התפתחות פיזית ונפשית בשלושת השביעונים הראשונים','מאמר','האדם נתפס כמורכב מארבעה גופים: הגוף הפיזי, הגוף האתרי, הגוף האסטרלי והגוף הרוחי. כל אחד מהם קשור לתחומים שונים של ההוויה האנושית ופועל ברמות שונות של קיום. בחינוך ולדורף…','./lib-p3088.html','ירון זנבל','2025',0,1025,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p3020','הפוך גוטה. הפוך','מאמר','המאמר משווה בין שתי מערכות גדולות – בנקאית וחינוכית – ומנתח את ניסיונותיהן ליישם טכנולוגיה מתקדמת. במערכת הבנקאית, ניסיון להחליף סניפים מסורתיים במערכת מתוקשבת עתידנית…','./lib-p3020.html','ירון זנבל','2025',0,1026,strftime('%s','now'),strftime('%s','now'));
