INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2810','תקופות בוטניקה בכיתות ה''-ו'': לצמוח עם הילדים','מאמר','מפשוט למורכב, מרך למעוצב, מדמיוני למציאותי, מתלות לעצמאות. התבגרות. יא וַיֹּאמֶר אֱלֹהִים, תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע, עֵץ פְּרִי עֹשֶׂה פְּרִי…','./lib-p2810.html','ירון זנבל','2022',0,1028,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2803','לספר סיפורים (בע"פ) בחינוך ולדורף','מאמר','חינוך ולדורף מושתת על סיפור סיפורים. מהסיפור במעגל בגן הילדים ועד שיעורי המדעים בתיכון. ולא סתם סיפור – הכוונה היא לסיפור בעל פה, ללא ספר. מדוע הסיפור בחינוך ולדורף כה…','./lib-p2803.html','ירון זנבל','2022',0,1029,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2665','תפקיד מנהל בית הספר, ניהול משותף, מנהיגות ואחריות בבית ספר ולדורף','מאמר','אפריל 2020 הקדמה המאמר נשען על חומרים שונים מעולם המנהיגות האופקית. העריכה שלו נעשית בפסח, בתקופת הקורונה. בתקופה זו המתח שבין כוחות עבר ועתיד מתחדד. הדרישה להתחדשות…','./lib-p2665.html','רונן האן','2020',0,1030,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2650','למידה מרחוק מתוך השקפת חינוך וולדורף','מאמר','מאת: Martyn Rawson תרגום: גיא פרי הקדמה בהינתן העוצר הנוכחי והצורך הכפוי בלמידה מרחוק, מהבית, כדאי להקדיש זמן לחשיבה מחודשת של עקרונות הלמידה על פי השקפת חינוך וולדורף.…','./lib-p2650.html','מרטין רואוסון','2020',0,1031,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2591','הכיתה כמרחב להתחנכות','מאמר','או הדרך הפנימית של מורה הכיתה מאת: אורי עברי פורסם ב אדם עולם באביב 2013 שתי סיבות מביאות אותי לכתוב מאמר זה על דרכו הפנימית של המורה. ראשית, כמורה וותיק יחסית מצאתי…','./lib-p2591.html','אורי עברי','2020',0,1032,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2585','על שאלות חינוכיות בגיל ההתבגרות המינית (כיתות ו'', ז'', ח''): ליווי חינוכי וחינוך מיני','מאמר','מבוא זה זמן רב שהשאלה כיצד נכון ללוות את שלב ההתעוררות של נערות ונערים לזהותם האישית בגיל טרום הנעורים (כיתות ז-ח) חייה בתוכי. האם ההנחיות ששטיינר נתן בהתייחסו ללווי…','./lib-p2585.html','אורי עברי','2020',0,1033,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2398','הקולגיום','מאמר','מאמר זה מציע תפיסה כללית לבניית ישיבות צוות. במונח צוות אפשר להכליל מחלקה, ענף גם כל העובדים של ארגון לא גדול , למשל עד 60-70 משתתפים. הדוגמא וההשראה מתבססות על ישיבת…','./lib-p2398.html','רונן האן','2018',0,1034,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2391','זו לא התורה כולה – חינוך ולדורף ויהדות','מאמר','שטיינר דיבר על רליגיוזיות כרגש עמוק של הכרת תודה, ממשיכיו בחינוך ולדורף מתייחסים ללאומיות כבסיס לתחושת שייכות. כיצד משלבים יהדות וציונות בלימודי ולדורף בישראל? הרב…','./lib-p2391.html','אילה שני','2018',0,1035,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2325','עיצוב מרחב פיזי ברוח החינוך','מאמר','תכנון מבנה גן ילדים ולדורף בהרדוף האם וכיצד ניתן לתכנן מבנה כך שיוכל לתמוך בפעילויות חינוכיות, באווירה חינוכית ובערכים חינוכיים מסוימים? כיצד אפשר לחבר בין תכנון אדריכלי…','./lib-p2325.html','דרור צור וגלעד גולדשמידט','2018',0,1036,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2328','חינוך ולדורף ואתגרי הזמן','מאמר','מאת: אורי עברי [המאמר ב קובץ word ] הציטוטים מובאים מתוך סדרת ההרצאות של שטיינר שנקראות בעברית "חינוך וחיים רוחיים מודרנים" ואשר ניתנו כבסיס לייסוד חינוך ולדורף באנגליה.…','./lib-p2328.html','אורי עברי','2018',0,1037,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2327','דרכו הפנימית של המורה או "חנוך לנער לפי דרכו"','מאמר','מאת: אורי עברי [המאמר כ קובץ word ] שתי סיבות מביאות אותי לכתוב מאמר זה על דרכו הפנימית של המורה. ראשית כמורה בשבתון מצאתי עצמי מלווה מורים עמיתים בדרכם ומתוך עבודתי עלו…','./lib-p2327.html','אורי עברי','2018',0,1038,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2323','22 שאלות ותשובות על חינוך ולדורף','מאמר','מה מיוחד בבית ספר ולדורף? הרושם הראשון שמקבלים מהנעשה בבית ספר יסודי ברוח חינוך ולדורף הוא של פעילות אמנותית מתמשכת: הילדים שרים, מנגנים, רוקדים, מציירים, רושמים,…','./lib-p2323.html','גלעד גולדשמידט','2018',0,1039,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2038','א. מבוא','ספר','הספר "חינוך ולדורף – עקרונות ויישומים" נכתב על-ידי מורי בית הספר ולדורף הרדוף, סתיו 2000 הדברים שיובאו לעיל מנסים להציג את חינוך ולדורף כפי שהוא התפתח ומיושם בבתי הספר…','./lib-p2038.html','מורי בית הספר ולדורף הרדוף','2000',0,2000,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2042','ב. יסודות חינוך ולדורף','ספר','חינוך ולדורף נוסד בתחילת המאה על-ידי המחנך, הפילוסוף והוגה הדעות רודולף שטיינר (1861-1925). בית-הספר הראשון הוקם כבית-ספר לילדי פועלים במפעל "ולדורף-אסטוריה" בעיר…','./lib-p2042.html','מורי בית הספר ולדורף הרדוף','2000',0,2001,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2045','ג. בתי-ספר ולדורף בארץ','ספר','בארץ פועלים כיום שלשה בתי- ספר ולדורף: בירושלים – בי"ס "אדם", עם תשע כיתות, א'' עד ט''; בטבעון – בי"ס "שקד", עם שמונה כיתות א'' עד ח''; ובי"ס ולדורף הרדוף, בקיבוץ הרדוף…','./lib-p2045.html','מורי בית הספר ולדורף הרדוף','2000',0,2002,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2047','ד. ניהול בית-הספר ועבודת המורים','ספר','כאשר התבקש רודולף שטיינר (מייסד חינוך ולדורף) לעזור בהקמת בית-הספר ולדורף הראשון (1919), הוא אסף סביבו קבוצת מורים וניסה להכשירם להוראה בתקופה הקצרה שעמדה לרשותם עד…','./lib-p2047.html','מורי בית הספר ולדורף הרדוף','2000',0,2003,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2051','ה. עבודה עם הורים – מעורבות הורים','ספר','השותפים הישירים להוויית החיים הבית-ספרית הנם הילדים, המורים וההורים. כאשר מנסים ליצור איכויות שהנן מעבר להקניית ידע ואינפורמציה, עולה שאלת החיים המשותפים בקהילת…','./lib-p2051.html','מורי בית הספר ולדורף הרדוף','2000',0,2004,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2054','ו. על כמה צדדים מעשיים','ספר','בפרקים הבאים יעשה הניסיון להביא בקיצור כמה מן הצדדים המעשיים של העבודה הפדגוגית בבית-הספר. בכל תאור צריך רק לקחת בחשבון, שאת הדברים החשובים ובעלי המשמעות אין אפשרות לתאר…','./lib-p2054.html','מורי בית הספר ולדורף הרדוף','2000',0,2005,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2059','ז. מחיי הכיתה – כמה דוגמאות למתודות ההוראה','ספר','בפרק זה יובאו כמה דוגמאות מעבודה של כיתות שונות בבתי-הספר ולדורף בארץ. בהביאנו דוגמאות מהעבודה המעשית של חיי בית-הספר יש לזכור שבבית-ספר ולדורף אין דרך אחת ויחידה ללמד…','./lib-p2059.html','מורי בית הספר ולדורף הרדוף','2000',0,2006,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2061','ח. סמכות וחופש – שאלת הדמוקרטיה בחינוך ולדורף','ספר','הדמוקרטיה הפכה בעת החדשה, ובמיוחד במאה ה- 20 לאחד מהערכים המרכזיים של התרבות המערבית. אולם הדמוקרטיה אינה תופעה מובנת מאליה בתולדות האנושות. את רובה הגדול של עברה עשתה…','./lib-p2061.html','מורי בית הספר ולדורף הרדוף','2000',0,2007,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2062','ט. הערכה בחינוך ולדורף','ספר','תהליכי הערכה נכונים אינם מנותקים מהתהליך החינוכי אותו הם אמורים להעריך. תהליכי הערכה מנותקים וכביכול אוביקטיביים אינם חלק מהתהליך הלימודי אליו שואף בית-ספר ולדורף. כמו…','./lib-p2062.html','מורי בית הספר ולדורף הרדוף','2000',0,2008,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2063','י. הכשרת המורים ברוח חינוך ולדורף – סמינר המורים','ספר','המורים המלמדים בבית-הספר עברו כולם (או שעדיין עוברים במקביל לעבודתם) הכשרת מורים ברוח חינוך ולדורף. הכשרה זו נמשכת כשלוש שנים ומהווה תנאי לקבלת המורה לעבודה בבית-הספר.…','./lib-p2063.html','מורי בית הספר ולדורף הרדוף','2000',0,2009,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2064','יא. כמה צדדים טכניים','ספר','א. מעמד חוקי והכרה בתי-ספר ולדורף בארץ הוכרו כבתי-ספר ממלכתיים, רשמים במסגרת משרד החינוך. בתי-הספר מקבלים את התקציבים המגיעים לכל בית-ספר ונתונים לאותו פיקוח. עקב אופיים…','./lib-p2064.html','מורי בית הספר ולדורף הרדוף','2000',0,2010,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2065','יב. אנשים שונים אודות חינוך ולדורף','ספר','"אם היה לי ילד בגיל בית-ספר, הייתי שולחו לאחד מבתי-הספר ולדורף" סול בלו – סופר וחתן פרס נובל לספרות "רוב הילדים שמתחנכים במסגרת חינוך ולדורף הנם שמחים, נבונים, מקבלים,…','./lib-p2065.html','מורי בית הספר ולדורף הרדוף','2000',0,2011,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2066','יג. מדברי תלמידים בתיכון ולדורף הרדוף על בית ספרם','ספר','" … כאן זה לא רק כיף לי, ולא רק שהכל כה שונה, אלא כאן לומדים קשה ועובדים, אך יחד עם זה מאד נהנים. כאן אנחנו חיים בתוך הדרך שבה אנו רוצים לחיות." תלמידה בכיתה י'' "בבית…','./lib-p2066.html','מורי בית הספר ולדורף הרדוף','2000',0,2012,strftime('%s','now'),strftime('%s','now'));
INSERT OR REPLACE INTO library (id,title,kind,description,url,author,date,demo,position,created_at,updated_at) VALUES ('lb-p2067','יד. שירים ודקלומים מעבודות התלמידים','ספר','שיר המשאלה יש לי משאלה היא קטנה וגם גדולה שיהיה שלום בין ארצות ושיהיה שלום בין אחים ואחיות שנדע לאהוב כל אדם ואדם למרות שאף אחד לא מושלם. יש לי משאלה היא קטנה וגם גדולה…','./lib-p2067.html','מורי בית הספר ולדורף הרדוף','2000',0,2013,strftime('%s','now'),strftime('%s','now'));
